import React, { useEffect, useState, useRef } from "react";
import SockJS from "sockjs-client";
import { Client } from "@stomp/stompjs";
import axios from "axios";

const API_BASE = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

export default function LudoBoard({ gameId: propGameId, sessionId: propSessionId, token: propToken }) {
  const [boardState, setBoardState] = useState(null);
  const [currentPlayer, setCurrentPlayer] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [playerInfo, setPlayerInfo] = useState({});
  const [opponentInfo, setOpponentInfo] = useState({});
  const [diceValue, setDiceValue] = useState(null);
  const [diceHistory, setDiceHistory] = useState({ 1: [], 2: [] });
  const stompClientRef = useRef(null);

  const token = propToken || localStorage.getItem("authToken");
  const sessionId = propSessionId || localStorage.getItem("currentSessionId");
  const gameId = propGameId || localStorage.getItem("currentGameId");

  // Redirect if info missing
  useEffect(() => {
    if (!token || !sessionId || !gameId) {
      console.error("Missing token/sessionId/gameId, redirecting...");
      window.location.href = "/";
    }
  }, [token, sessionId, gameId]);

  // WebSocket connection
  useEffect(() => {
    if (!token || !sessionId) return;

    const socket = new SockJS(`${API_BASE}/ludo-ws?token=${encodeURIComponent(token)}`);
    const stompClient = new Client({
      webSocketFactory: () => socket,
      reconnectDelay: 5000,
      debug: () => {},
      onConnect: () => {
        stompClient.subscribe(`/topic/game/${sessionId}`, (msg) => {
          try {
            const state = JSON.parse(msg.body);
            setBoardState(state.playerTokens || []);
            setCurrentPlayer(state.currentPlayer ?? 0);
            setGameOver(state.gameOver || false);

            if (state.lastDiceValue !== undefined && state.currentPlayer !== undefined) {
              setDiceValue(state.lastDiceValue);
              setDiceHistory((prev) => ({
                ...prev,
                [state.currentPlayer]: [...(prev[state.currentPlayer] || []), state.lastDiceValue],
              }));
            }
          } catch (err) {
            console.error("Error parsing game state:", err);
          }
        });
      },
    });

    stompClient.activate();
    stompClientRef.current = stompClient;
    return () => stompClient.deactivate();
  }, [sessionId, token]);

  // Player and opponent info fetch
  useEffect(() => {
    if (!token) return;
    axios
      .get(`${API_BASE}/api/user/profile`, { headers: { Authorization: `Bearer ${token}` } })
      .then((res) => {
        setPlayerInfo(res.data);
        axios
          .get(`${API_BASE}/api/match/opponent/${sessionId}`, {
            headers: { Authorization: `Bearer ${token}` },
          })
          .then((oppRes) => setOpponentInfo(oppRes.data))
          .catch(() => {});
      })
      .catch((err) => console.error(err));
  }, [token, sessionId]);

  // Roll dice action
  const rollDice = () => {
    axios
      .post(`${API_BASE}/api/game/roll/${sessionId}`, {}, { headers: { Authorization: `Bearer ${token}` } })
      .catch((err) => alert(err.response?.data || "Error rolling dice"));
  };

  // Send move action
  const sendMove = (tokenIndex) => {
    if (!diceValue) {
      alert("First roll the dice!");
      return;
    }
    stompClientRef.current?.publish({
      destination: "/app/game/move",
      body: JSON.stringify({
        gameId: sessionId,
        playerId: currentPlayer,
        tokenIndex: tokenIndex,
        diceValue: diceValue,
      }),
    });
    setDiceValue(null);
  };

  // Cancel game action
  const cancelGame = () => {
    if (!window.confirm("Are you sure you want to cancel the game?")) return;
    axios
      .post(`${API_BASE}/api/game/leave`, { gameId: sessionId }, { headers: { Authorization: `Bearer ${token}` } })
      .then(() => {
        localStorage.removeItem("currentSessionId");
        localStorage.removeItem("currentGameId");
        window.location.href = "/";
      })
      .catch((err) => alert("Error cancelling game: " + (err.response?.data || err.message)));
  };

  if (gameOver) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-gray-900 text-white">
        <h2 className="text-3xl font-bold mb-4">🎉 Game Over 🎉</h2>
        <button
          className="px-6 py-3 bg-primary text-white rounded-lg hover:bg-indigo-600"
          onClick={() => (window.location.href = "/")}
        >
          Back to Home
        </button>
      </div>
    );
  }

  return (
    <div className="p-6 min-h-screen bg-gray-100">
      {/* Player Info */}
      <header className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <img
            src={playerInfo.avatarUrl || "/default-avatar.png"}
            alt="avatar"
            className="w-12 h-12 rounded-full border-2 border-primary"
          />
          <span className="text-lg font-semibold">{playerInfo.displayName || "Player"}</span>
        </div>
        <div className="flex items-center gap-3">
          <img
            src={opponentInfo.avatarUrl || "/default-avatar.png"}
            alt="avatar"
            className="w-12 h-12 rounded-full border-2 border-red-500"
          />
          <span className="text-lg font-semibold">{opponentInfo.displayName || "Opponent"}</span>
        </div>
      </header>

      {/* Board */}
      <div className="bg-white rounded-lg shadow-lg p-6">
        {boardState ? (
          <div className="grid grid-cols-2 gap-6">
            {boardState.map((tokens, playerIdx) => {
              const playerNumber = playerIdx + 1;
              return (
                <div
                  key={playerIdx}
                  className={`p-4 rounded-lg border-2 ${
                    currentPlayer === playerNumber ? "border-primary" : "border-gray-300"
                  }`}
                >
                  <h4
                    className={`text-lg font-bold mb-4 ${
                      currentPlayer === playerNumber ? "text-primary" : "text-gray-600"
                    }`}
                  >
                    {playerNumber === 1
                      ? playerInfo.displayName || "Player 1"
                      : opponentInfo.displayName || "Player 2"}
                  </h4>
                  <div className="flex flex-wrap gap-3">
                    {tokens.map((pos, tokenIdx) => (
                      <button
                        key={tokenIdx}
                        onClick={() => sendMove(tokenIdx)}
                        disabled={currentPlayer !== playerNumber}
                        className={`px-3 py-2 rounded-lg border ${
                          currentPlayer === playerNumber
                            ? "bg-secondary text-white hover:bg-yellow-500"
                            : "bg-gray-200 text-gray-600 cursor-not-allowed"
                        }`}
                      >
                        Token {tokenIdx + 1} ({pos})
                      </button>
                    ))}
                  </div>
                  <div className="mt-4 text-sm text-gray-500">
                    Rolls: {diceHistory[playerNumber]?.join(", ") || "No rolls yet"}
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <p className="text-center text-gray-500">Waiting for game to start...</p>
        )}
      </div>

      {/* Controls */}
      <div className="flex items-center gap-4 mt-6">
        <button
          onClick={rollDice}
          disabled={
            playerInfo.gameId &&
            !(
              playerInfo.gameId === (currentPlayer === 1 ? playerInfo.gameId : opponentInfo.gameId)
            )
          }
          className={`px-4 py-2 rounded-lg text-white ${
            currentPlayer === 1 ? "bg-primary hover:bg-indigo-600" : "bg-gray-400 cursor-not-allowed"
          }`}
        >
          🎲 Roll Dice
        </button>
        {diceValue && <span className="text-2xl font-bold text-secondary">{diceValue}</span>}
        <button
          onClick={cancelGame}
          className="px-4 py-2 rounded-lg bg-red-600 text-white hover:bg-red-700 ml-4"
        >
          Back
        </button>
      </div>
    </div>
  );
}
